package cl.duoc.tienda.proveedor.controller;
import cl.duoc.tienda.proveedor.dto.*; import cl.duoc.tienda.proveedor.model.*; import cl.duoc.tienda.proveedor.service.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/proveedores") @Tag(name="Proveedor",description="CRUD de proveedores") public class ProveedorController { private final ProveedorService service; public ProveedorController(ProveedorService s){service=s;} @GetMapping @Operation(summary="Listar proveedores") public ResponseEntity<List<Proveedor>> listar(){return ResponseEntity.ok(service.listar());} @GetMapping("/{id}") public ResponseEntity<Proveedor> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));} @PostMapping public ResponseEntity<Proveedor> crear(@Valid @RequestBody ProveedorRequest d){Proveedor e=service.guardar(d);return ResponseEntity.created(URI.create("/proveedores/"+e.getId())).body(e);} @PutMapping("/{id}") public ResponseEntity<Proveedor> actualizar(@PathVariable Long id,@Valid @RequestBody ProveedorRequest d){return ResponseEntity.ok(service.actualizar(id,d));} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();} }
